// Traduit la sortie du nœud IMAP en enveloppe de réponse. #645
//
// ⚠️ SUR SUCCÈS, NI `error` NI `error_code` : MCP discrimine sur la PRÉSENCE de la clé,
// pas sur sa valeur. Poser `error: null` fait lire un échec (mesuré sur Classroom).
const d = $input.first().json || {};

if (Object.prototype.hasOwnProperty.call(d, 'error')) {
  // Le nœud a nettoyé le message de tout secret avant de nous le passer.
  const auth = d.auth_failed === true;
  const code = auth ? 401 : 502;
  const statut = auth ? 'IMAP_AUTH_REJECTED' : 'IMAP_UPSTREAM_ERROR';
  return [{ json: {
    success: false,
    error_code: statut,
    error: { code, message: String(d.error), status: statut },
    meta: { provider: 'imap', imap_code: d.imap_code || null },
    _trace: { http_status: code, noeud: 'Qualifier la réponse' },
  } }];
}

return [{ json: {
  success: true,
  data: d,
  meta: { provider: 'imap' },
  _trace: { http_status: 200, noeud: 'Qualifier la réponse' },
} }];

// Repli du Switch : `action` fournie mais non reconnue. #645
//
// ⚠️ Cette branche doit rester ATTEINGNABLE. Sur `Category Detect`, le nœud équivalent
// est câblé mais inatteignable parce que la variable testée ne prend que deux valeurs —
// et un ruleset inconnu y ressort en `500 PARSE_ERROR` au lieu du message utile.
const action = $input.first().json?.body?.action;
return [{ json: {
  success: false,
  error_code: 'TOOL_ROUTE_UNKNOWN',
  error: {
    code: 400,
    message: `action inconnue : ${JSON.stringify(action)}. Attendu : list_folders, search, fetch_email.`,
    status: 'TOOL_ROUTE_UNKNOWN',
  },
  meta: { provider: 'imap' },
  _trace: { http_status: 400, noeud: 'Route inconnue' },
} }];
